// Sample input. Replace source_url with your own long-form video URL and adjust config.
return [{ json: {
  source_url: 'https://www.youtube.com/watch?v=EXAMPLE1234',
  clip_count: 6,
  clip_length_sec: 45,
  first_slot_iso: '2026-10-01T08:00:00Z',
  platforms: ['tiktok', 'instagram_reels', 'youtube_shorts'],
  captions_style: 'karaoke-bold',
  branding: 'lower-third @yourhandle',
  background_music: 'subtle-lofi',
  slot_offsets_hours: [0, 4, 11]
} }];

const items = $input.all();
if (!items.length) throw new Error('No input items');
return items.map(({ json: j }) => {
  const e = [];
  try { const u = new URL(j.source_url); if (!/^https?:$/.test(u.protocol)) e.push('source_url must be http(s)'); } catch { e.push('source_url must be a valid URL'); }
  if (!Number.isInteger(j.clip_count) || j.clip_count < 1 || j.clip_count > 50) e.push('clip_count must be an integer 1-50');
  if (!Number.isFinite(j.clip_length_sec) || j.clip_length_sec < 5 || j.clip_length_sec > 180) e.push('clip_length_sec must be 5-180');
  if (isNaN(Date.parse(j.first_slot_iso || ''))) e.push('first_slot_iso must be an ISO datetime');
  if (!Array.isArray(j.platforms) || !j.platforms.length) e.push('platforms must be a non-empty array');
  if (!Array.isArray(j.slot_offsets_hours) || !j.slot_offsets_hours.every(n => Number.isFinite(n))) e.push('slot_offsets_hours must be an array of numbers');
  if (e.length) throw new Error('Invalid input: ' + e.join('; '));
  return { json: j };
});

const out = [];
const hash = s => { let x = 5381; for (const c of s) x = ((x << 5) + x + c.charCodeAt(0)) >>> 0; return x.toString(16); };
for (const { json: j } of $input.all()) {
  const base = new Date(j.first_slot_iso).getTime();
  const offsets = j.slot_offsets_hours;
  const seen = new Set();
  for (let i = 0; i < j.clip_count; i++) {
    for (const platform of j.platforms) {
      const dayIndex = Math.floor(i / offsets.length);
      const offsetHours = offsets[i % offsets.length] + dayIndex * 24;
      const scheduled = new Date(base + offsetHours * 3600 * 1000).toISOString();
      const clip_id = hash(j.source_url + '|' + i + '|' + platform);
      if (seen.has(clip_id)) continue; // idempotent within run
      seen.add(clip_id);
      out.push({ json: {
        clip_id,
        source_url: j.source_url,
        clip_index: i + 1,
        platform,
        target_length_sec: j.clip_length_sec,
        captions_style: j.captions_style || '',
        branding: j.branding || '',
        background_music: j.background_music || '',
        scheduled_at: scheduled,
        status: 'planned',
        clip_render: 'MANUAL_HANDOFF: render this clip with your self-hosted/third-party clipper, then attach the file',
        publish: 'DRAFT: upload requires human approval; no auto-post implemented'
      } });
    }
  }
}
if (!out.length) throw new Error('No clip tasks produced');
return out;

const sourceId="DbzL_FByZ6t";
const sourceUrl="https://www.instagram.com/billsabertv/reel/DbzL_FByZ6t/";
const variant='USER_STACK';
const seen=new Set();
const hash=s=>{let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return (h>>>0).toString(16).padStart(8,'0');};
return $input.all().map(({json:j},i)=>{
  const recordKey=String(j.row_id||j.clip_id||j.note_id||j.fileName||j.output_path||j.title||i);
  const idempotencyKey=hash(sourceId+'|'+recordKey);
  if(seen.has(idempotencyKey)) throw new Error('Duplicate output in one execution: '+idempotencyKey);
  seen.add(idempotencyKey);
  return {json:{...j,source_provenance:{source_id:sourceId,source_url:sourceUrl,variant},idempotency_key:idempotencyKey,review_status:'needs_human_review',review_notes:Array.isArray(j.review_notes)?j.review_notes:[],external_actions_enabled:false}};
});
